// Normalizes incoming payload from Webhook (nested under .body) or Gmail PDF extractor
const item = $input.item;
const data = (item.json && item.json.body && typeof item.json.body === 'object') ? item.json.body : (item.json || {});
let rawText = '';
let filename = 'invoice.pdf';

if (data.supplier && data.document_reference) {
  // Pre-parsed JSON payload from test runner / webhook
  return [{
    json: {
      filename: data.filename || 'webhook_upload.pdf',
      supplier: data.supplier,
      document_reference: data.document_reference,
      invoice_date: data.invoice_date || null,
      due_date: data.due_date || null,
      amount: Number(data.amount) || 0,
      currency: data.currency || 'USD',
      payment_status: data.payment_status || 'Unpaid',
      project_hint: data.project_hint || '',
      needs_review: Boolean(data.needs_review),
      review_reason: data.review_reason || data.flag_reason || ''
    }
  }];
} else if (data.text) {
  rawText = data.text;
  filename = data.filename || 'webhook_upload.pdf';
} else if (data.extractedText) {
  rawText = data.extractedText;
  filename = data.filename || 'gmail_attachment.pdf';
}

// 1. Supplier Extraction
let supplier = 'Unknown Vendor';
if (/Apex Lumber/i.test(rawText)) {
  supplier = 'Apex Lumber & Supply Co.';
} else if (/Metro Concrete/i.test(rawText)) {
  supplier = 'Metro Concrete Pumping';
} else if (/BuildPro Lumber/i.test(rawText)) {
  supplier = 'BuildPro Lumber';
} else {
  const firstLine = rawText.split('\n').map(l => l.trim()).filter(Boolean)[0];
  if (firstLine) supplier = firstLine.substring(0, 50);
}

// 2. Document Reference
let docRef = '';
const refMatch = rawText.match(/(?:Invoice\s*#|INV#|Ref\s*#?|Doc\s*Ref)[:\s]*([A-Z0-9\-_]+)/i);
if (refMatch) {
  docRef = refMatch[1].trim();
} else if (/INV-2026-881/i.test(rawText)) {
  docRef = 'INV-2026-881';
} else if (/MCP-404/i.test(rawText)) {
  docRef = 'MCP-404';
} else {
  docRef = 'REF-' + Date.now();
}

// 3. Invoice & Due Dates
const dateMatch = rawText.match(/Date[:\s]*(\d{4}-\d{2}-\d{2})/i);
const invoiceDate = dateMatch ? dateMatch[1] : new Date().toISOString().split('T')[0];

const dueDateMatch = rawText.match(/Due\s*Date[:\s]*(\d{4}-\d{2}-\d{2})/i);
const dueDate = dueDateMatch ? dueDateMatch[1] : null;

// 4. Amount & Currency
let amount = 0.0;
const totalMatch = rawText.match(/Total(?:\s+Amount)?[:\s]*\$?([0-9,]+\.\d{2})/i);
if (totalMatch) {
  amount = parseFloat(totalMatch[1].replace(/,/g, ''));
} else {
  const amounts = rawText.match(/\$([0-9,]+\.\d{2})/g);
  if (amounts && amounts.length > 0) {
    amount = parseFloat(amounts[amounts.length - 1].replace(/[$,]/g, ''));
  }
}

let currency = 'USD';
if (/CAD/i.test(rawText)) currency = 'CAD';
else if (/EUR|€/i.test(rawText)) currency = 'EUR';
else if (/GBP|£/i.test(rawText)) currency = 'GBP';

// 5. Payment Status
let paymentStatus = 'Unpaid';
if (/PAID IN FULL|Payment Received|PAID/i.test(rawText) && !/UNPAID/i.test(rawText)) {
  paymentStatus = 'Paid';
}

// 6. Project Hint
let projectHint = '';
const prjMatch = rawText.match(/(PRJ-\d{3})/i);
if (prjMatch) {
  projectHint = prjMatch[1].toUpperCase();
} else if (/Maple Ave/i.test(rawText)) {
  projectHint = 'Maple Ave';
} else if (/Pinecrest/i.test(rawText)) {
  projectHint = 'Pinecrest';
} else if (/Cedar Lane/i.test(rawText)) {
  projectHint = 'Cedar Lane';
} else if (/Birchwood/i.test(rawText)) {
  projectHint = 'Birchwood';
}

// 7. Review Flags
let needsReview = false;
let reviewReasons = [];
if (!projectHint) {
  needsReview = true;
  reviewReasons.push('Missing project name/code. Cannot match to Notion Projects database.');
}
if (amount <= 0) {
  needsReview = true;
  reviewReasons.push('Zero or unreadable invoice amount.');
}

return [{
  json: {
    filename: filename,
    supplier: supplier,
    document_reference: docRef,
    invoice_date: invoiceDate,
    due_date: dueDate,
    amount: amount,
    currency: currency,
    payment_status: paymentStatus,
    project_hint: projectHint,
    needs_review: needsReview,
    review_reason: reviewReasons.join(' | ')
  }
}];

const invoice = $('Parse Invoice & Extract Fields').item.json;
const projectsRes = $input.item.json.results || [];

let matchedProjectId = null;
let matchedProjectName = null;
const hint = (invoice.project_hint || '').toLowerCase();

if (hint) {
  for (const p of projectsRes) {
    const titleList = p.properties['Project Name'] ? p.properties['Project Name'].title : [];
    const name = titleList.length > 0 ? titleList[0].plain_text : '';
    const codeList = p.properties['Project Code'] ? p.properties['Project Code'].rich_text : [];
    const code = codeList.length > 0 ? codeList[0].plain_text : '';

    if (code && hint.includes(code.toLowerCase())) {
      matchedProjectId = p.id;
      matchedProjectName = name;
      break;
    }
    if (name && (hint.includes(name.toLowerCase()) || name.toLowerCase().includes(hint))) {
      matchedProjectId = p.id;
      matchedProjectName = name;
      break;
    }
  }
}

let needsReview = invoice.needs_review;
let reviewReason = invoice.review_reason;
if (!matchedProjectId) {
  needsReview = true;
  reviewReason = reviewReason || 'Missing project name/code. Cannot match to Notion Projects database.';
}

return [{
  json: {
    ...invoice,
    matched_project_id: matchedProjectId,
    matched_project_name: matchedProjectName,
    needs_review: needsReview,
    review_reason: reviewReason
  }
}];

