parameters.jsCode:
const meta = $('Match Project & Verify Flags').item.json;
const isUpdate = Boolean($('Check for Duplicate Invoice').item.json.results && $('Check for Duplicate Invoice').item.json.results.length > 0);

let action = 'CREATED';
if (isUpdate) {
  action = 'UPDATED (Deduplicated)';
} else if (meta.needs_review) {
  action = 'FLAGGED FOR REVIEW';
}

const message = `[Automation Alert] Cost Ingestion: ${action}\n\n` +
  `• Supplier: ${meta.supplier}\n` +
  `• Doc Ref: ${meta.document_reference}\n` +
  `• Amount: $${meta.amount.toFixed(2)} ${meta.currency}\n` +
  `• Status: ${meta.payment_status}\n` +
  `• Project: ${meta.matched_project_name || 'Unassigned / Needs Review'}\n` +
  (meta.needs_review ? `• Flag Reason: ${meta.review_reason}\n` : '') +
  `• File: ${meta.filename}`;

return [{
  json: {
    action: action,
    summary_message: message,
    supplier: meta.supplier,
    doc_ref: meta.document_reference,
    amount: meta.amount,
    status: meta.payment_status,
    needs_review: meta.needs_review
  }
}];
